async function scanBundle(input, deliver) {
  let count = 0;
  let line = 1;

  try {
    const decoder = new TextDecoder("utf-8", { ignoreBOM: true });
    const fragments = [];

    async function finishLine(tail) {
      if (tail.length > 0) fragments.push(tail);
      const text = fragments.join("");
      fragments.length = 0;
      const currentLine = line++;

      if (text.trim() === "") return true;

      let value;
      try {
        value = JSON.parse(text);
      } catch {
        const error = new Error(`Invalid JSON on line ${currentLine}`);
        error.code = "BAD_LINE";
        error.line = currentLine;
        throw error;
      }

      count++;
      return (await deliver(value, currentLine)) !== false;
    }

    while (true) {
      const chunk = await input.read();

      if (chunk === null) {
        await finishLine(decoder.decode());
        return count;
      }

      let start = 0;
      while (start < chunk.length) {
        const newline = chunk.indexOf(10, start);

        if (newline === -1) {
          const fragment = decoder.decode(chunk.subarray(start), {
            stream: true
          });
          if (fragment.length > 0) fragments.push(fragment);
          break;
        }

        const tail = decoder.decode(chunk.subarray(start, newline));
        if (!(await finishLine(tail))) return count;
        start = newline + 1;
      }
    }
  } finally {
    await input.close();
  }
}
